package router

// webUIHTML is intentionally embedded so the fleet needs only the model-router
// binary; no Node runtime or separate static-file service is required.
const webUIHTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>model-router</title>
<style>
:root{color-scheme:dark;--bg:#0d1117;--panel:#161b22;--panel2:#21262d;--line:#30363d;--text:#e6edf3;--muted:#8b949e;--green:#3fb950;--yellow:#d29922;--red:#f85149;--blue:#58a6ff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}button,select,input,textarea{font:inherit;color:inherit;background:var(--panel2);border:1px solid var(--line);border-radius:6px;padding:7px 9px}button{cursor:pointer}button:hover{border-color:var(--blue)}button.primary{background:#1f6feb;border-color:#388bfd;color:white}button.danger{color:#ff7b72}.shell{max-width:1500px;margin:auto;padding:20px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.brand{font-size:22px;font-weight:700}.sub{color:var(--muted)}.health{display:flex;align-items:center;gap:8px;color:var(--muted)}.dot{width:9px;height:9px;border-radius:50%;background:var(--green);display:inline-block}.tabs{display:flex;gap:5px;border-bottom:1px solid var(--line);margin-bottom:16px}.tab{border:0;border-radius:6px 6px 0 0;background:transparent;color:var(--muted)}.tab.active{background:var(--panel);color:var(--text);border:1px solid var(--line);border-bottom-color:var(--panel)}.view{display:none}.view.active{display:block}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.card{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:14px}.card h3{margin:0 0 10px;font-size:15px}.metric{font-size:24px;font-weight:700}.metric small{font-size:12px;color:var(--muted);font-weight:400}.section{margin:16px 0}.section-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.section-title h2{font-size:17px;margin:0}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:8px}.table{width:100%;border-collapse:collapse;min-width:720px}.table th,.table td{text-align:left;padding:9px 10px;border-bottom:1px solid var(--line);white-space:nowrap}.table th{color:var(--muted);font-weight:500;background:var(--panel)}.table tr:last-child td{border-bottom:0}.state{font-size:12px;padding:2px 7px;border-radius:99px;background:var(--panel2);color:var(--muted)}.state.running{color:var(--green)}.state.starting{color:var(--yellow)}.state.failed{color:var(--red)}.state.peer,.state.selector{color:var(--blue)}.actions{display:flex;gap:6px}.form{display:grid;gap:10px}.form label{display:grid;gap:5px;color:var(--muted)}.form label span{font-size:12px}.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}.playground{display:grid;grid-template-columns:minmax(240px,340px) 1fr;gap:14px}.output{min-height:260px;white-space:pre-wrap;overflow:auto;background:#080b0f;border:1px solid var(--line);border-radius:7px;padding:12px;font-family:ui-monospace,SFMono-Regular,monospace}.chat-msg{margin:0 0 10px}.chat-msg b{color:var(--blue)}.error{color:var(--red);white-space:pre-wrap}.image-result img{max-width:100%;max-height:600px;border-radius:6px}.logs{height:430px;overflow:auto;background:#080b0f;border:1px solid var(--line);border-radius:7px;padding:10px;font:12px/1.5 ui-monospace,SFMono-Regular,monospace;white-space:pre-wrap}.muted{color:var(--muted)}.notice{padding:10px;border:1px solid #9e6a03;background:#2d2106;border-radius:7px;color:#e3b341;margin-bottom:12px}@media(max-width:800px){.playground{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}.two{grid-template-columns:1fr}}
</style>
</head>
<body>
<div class="shell">
  <header class="top"><div><div class="brand">model-router</div><div class="sub" id="node">Loading node status…</div></div><div class="health"><span class="dot"></span><span id="health">checking health</span></div></header>
  <nav class="tabs"><button class="tab active" data-tab="dashboard">Dashboard</button><button class="tab" data-tab="chat">Chat</button><button class="tab" data-tab="image">Image</button><button class="tab" data-tab="logs">Logs & metrics</button></nav>

  <main id="dashboard" class="view active">
    <div class="grid" id="gpu-cards"></div>
    <section class="section"><div class="section-title"><h2>Models</h2><button onclick="refresh()">Refresh</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Model</th><th>Type</th><th>State</th><th>VRAM</th><th>Action</th></tr></thead><tbody id="models"></tbody></table></div></section>
    <section class="section"><div class="section-title"><h2>Peers</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Node</th><th>GPU</th><th>Free VRAM</th><th>Loaded</th><th>Last update</th></tr></thead><tbody id="peers"></tbody></table></div></section>
  </main>

  <main id="chat" class="view"><div class="playground"><section class="card"><h3>Chat playground</h3><div class="form"><label><span>Model</span><select id="chat-model"></select></label><label><span>Message</span><textarea id="chat-prompt" rows="8">Say hello and identify yourself.</textarea></label><div class="two"><label><span>Max tokens</span><input id="chat-tokens" type="number" value="256" min="1"></label><label><span>Temperature</span><input id="chat-temp" type="number" value="0.7" min="0" step="0.1"></label></div><button class="primary" onclick="sendChat()">Send streaming request</button></div></section><section class="card"><h3>Response</h3><div id="chat-output" class="output muted">Responses appear here.</div></section></div></main>

  <main id="image" class="view"><div class="playground"><section class="card"><h3>Image playground</h3><div class="notice">Image requests use the router's <code>/sdapi/v1/txt2img</code> compatibility endpoint.</div><div class="form"><label><span>Model (optional; path default if empty)</span><select id="image-model"><option value="">Path default</option></select></label><label><span>Prompt</span><textarea id="image-prompt" rows="5">A small red square on a white background</textarea></label><label><span>Negative prompt</span><textarea id="image-negative" rows="3"></textarea></label><div class="two"><label><span>Width</span><input id="image-width" type="number" value="512" min="64" step="64"></label><label><span>Height</span><input id="image-height" type="number" value="512" min="64" step="64"></label></div><div class="two"><label><span>Steps</span><input id="image-steps" type="number" value="8" min="1"></label><label><span>Seed</span><input id="image-seed" type="number" value="-1"></label></div><button class="primary" onclick="generateImage()">Generate image</button></div></section><section class="card"><h3>Result</h3><div id="image-output" class="image-result muted">Generated images appear here.</div></section></div></main>

  <main id="logs" class="view"><div class="grid"><section class="card"><h3>GPU metrics</h3><div id="metrics" class="output">Loading metrics…</div></section><section class="card"><h3>Router events</h3><div id="logs-output" class="logs">Loading logs…</div></section></div></main>
</div>
<script>
(function(){
  let status={models:[],telemetry:{},peers:{}};
  const $=id=>document.getElementById(id);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.tab).classList.add('active');});
  async function json(url,opts){const r=await fetch(url,opts);const text=await r.text();let data;try{data=JSON.parse(text)}catch(e){data={error:text}}if(!r.ok)throw new Error(data.error||text||('HTTP '+r.status));return data}
  window.refresh=async function(){try{status=await json('/_router/status');$('node').textContent='Node: '+status.node+' · updated '+new Date().toLocaleTimeString();renderGPUs();renderModels();renderPeers();fillSelectors();$('health').textContent='healthy'}catch(e){$('health').textContent=e.message}}
  function renderGPUs(){const gs=status.telemetry&&status.telemetry.gpus||[];$('gpu-cards').innerHTML=gs.map(g=>'<section class="card"><h3>GPU '+esc(g.index)+' · '+esc(g.name)+'</h3><div class="metric">'+esc(g.free_mb)+' <small>MB free</small></div><div class="sub">'+esc(g.total_mb)+' MB total</div></section>').join('')||'<section class="card muted">No GPU telemetry available.</section>'}
  function renderModels(){const rows=(status.models||[]).map(m=>{const type=m.type||'model';const state=m.state||type;const can=type==='model';return '<tr><td>'+esc(m.id)+(m.name?'<div class="sub">'+esc(m.name)+'</div>':'')+'</td><td><span class="state '+esc(type)+'">'+esc(type)+'</span></td><td><span class="state '+esc(state)+'">'+esc(state)+'</span></td><td>'+((m.vram_mb||0)+' MB')+'</td><td>'+(can?'<div class="actions"><button onclick="loadModel('+JSON.stringify(m.id)+')">Load</button><button class="danger" onclick="unloadModel('+JSON.stringify(m.id)+')">Unload</button></div>':'—')+'</td></tr>'}).join('');$('models').innerHTML=rows||'<tr><td colspan="5" class="muted">No models.</td></tr>'}
  function renderPeers(){const ps=status.peers||{};$('peers').innerHTML=Object.keys(ps).sort().map(n=>{const p=ps[n]||{};const gs=p.gpus||[];return '<tr><td>'+esc(n)+'</td><td>'+esc(gs.map(g=>g.name).join(', ')||'—')+'</td><td>'+esc(gs.map(g=>g.free_mb+' MB').join(', ')||'—')+'</td><td>'+esc((p.loaded_models||[]).join(', ')||'—')+'</td><td>'+esc(p.timestamp?new Date(p.timestamp*1000).toLocaleTimeString():'—')+'</td></tr>'}).join('')||'<tr><td colspan="5" class="muted">No fresh peer telemetry.</td></tr>'}
  function fillSelectors(){const models=(status.models||[]).filter(m=>m.type==='model'||m.type==='selector'||m.type==='peer');const opts=models.map(m=>'<option value="'+esc(m.id)+'">'+esc(m.id)+'</option>').join('');$('chat-model').innerHTML=opts||'<option>No models</option>';const imgs=(status.models||[]).filter(m=>m.type==='model'&&/image|sd|krea|flux|z-|juggernaut|ltx|minimax/i.test((m.id||'')+' '+(m.name||'')));$('image-model').innerHTML='<option value="">Path default</option>'+imgs.map(m=>'<option value="'+esc(m.id)+'">'+esc(m.id)+'</option>').join('')}
  window.loadModel=async function(id){try{await json('/_router/load',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model_id:id})});await refresh()}catch(e){alert('Load failed: '+e.message)}}
  window.unloadModel=async function(id){try{await json('/_router/unload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model_id:id})});await refresh()}catch(e){alert('Unload failed: '+e.message)}}
  window.sendChat=async function(){const out=$('chat-output');out.className='output';out.textContent='';const body={model:$('chat-model').value,messages:[{role:'user',content:$('chat-prompt').value}],max_tokens:Number($('chat-tokens').value)||256,temperature:Number($('chat-temp').value)||0.7,stream:true};try{const r=await fetch('/v1/chat/completions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw new Error(await r.text());const reader=r.body.getReader(),dec=new TextDecoder();let buf='';while(true){const x=await reader.read();if(x.done)break;buf+=dec.decode(x.value,{stream:true});const lines=buf.split('\n');buf=lines.pop();for(const line of lines){if(!line.startsWith('data:'))continue;const raw=line.slice(5).trim();if(raw==='[DONE]')continue;try{const d=JSON.parse(raw),c=d.choices&&d.choices[0]&&d.choices[0].delta||{};out.textContent+=(c.reasoning_content||'')+(c.content||'')}catch(e){}}}if(!out.textContent)out.textContent='Request completed with no text output.'}catch(e){out.className='output error';out.textContent=e.message}}
  window.generateImage=async function(){const out=$('image-output');out.className='image-result';out.textContent='Generating…';const body={prompt:$('image-prompt').value,negative_prompt:$('image-negative').value,width:Number($('image-width').value),height:Number($('image-height').value),steps:Number($('image-steps').value),seed:Number($('image-seed').value)};if($('image-model').value)body.model=$('image-model').value;try{const d=await json('/sdapi/v1/txt2img',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const imgs=d.images||[];out.innerHTML=imgs.length?imgs.map(x=>'<img src="data:image/png;base64,'+x+'">').join(''):'<span class="muted">No images returned.</span>'}catch(e){out.className='image-result error';out.textContent=e.message}}
  async function logs(){try{const d=await json('/_router/logs');$('logs-output').textContent=(d.entries||[]).join('\n')||'No router events yet.'}catch(e){$('logs-output').textContent=e.message}try{$('metrics').textContent=await (await fetch('/metrics')).text()}catch(e){$('metrics').textContent=e.message}}
  refresh();logs();setInterval(refresh,3000);setInterval(logs,3000);
})();
</script>
</body></html>`
